foreignObject.div:
:root {--primary:#3B82F6;--accent:#10B981;--text:#1f2937;--muted:#6b7280;--bg:#f8fafc;}
*{box-sizing:border-box} body{margin:0;font-family:"Yu Gothic","Hiragino Kaku Gothic ProN",sans-serif;color:var(--text);line-height:1.7;background:var(--bg)}
a{color:var(--primary);text-decoration:none} .container{max-width:1080px;margin:0 auto;padding:0 20px}
header{position:sticky;top:0;background:#fff;border-bottom:1px solid #e5e7eb;z-index:10}
.nav{display:flex;justify-content:space-between;align-items:center;padding:14px 0}.logo{font-weight:700;color:var(--text)}
.nav-links{display:flex;gap:16px;align-items:center;flex-wrap:wrap}.btn{display:inline-block;background:var(--primary);color:#fff;padding:12px 18px;border-radius:10px;font-weight:700}
.btn.secondary{background:#fff;color:var(--primary);border:1px solid var(--primary)}
.hero{background:linear-gradient(135deg,#dbeafe,#eff6ff);padding:72px 0}.hero h1{font-size:42px;line-height:1.3;margin:0 0 12px}
section{padding:56px 0}.card{background:#fff;border:1px solid #e5e7eb;border-radius:14px;padding:20px;margin-bottom:14px}
.grid-2{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.grid-3{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}
footer{background:#0f172a;color:#e2e8f0;padding:36px 0;margin-top:40px} footer a{color:#bfdbfe}
.table{width:100%;border-collapse:collapse;background:#fff}.table th,.table td{border:1px solid #e5e7eb;padding:10px;text-align:left}
form .row{margin-bottom:14px} input,select,textarea{width:100%;padding:10px;border:1px solid #d1d5db;border-radius:8px}
@media (max-width:768px){.hero h1{font-size:32px}.grid-2,.grid-3{grid-template-columns:1fr}.nav{flex-direction:column;align-items:flex-start;gap:10px}}
